def transform(grid):
    from collections import deque
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    out = g.copy()
    ys, xs = np.where(g == 2)
    sy, sx = int(ys[0]), int(xs[0])
    # initial direction: away from the border the red seed touches
    if sx == 0: d = (0, 1)
    elif sx == W - 1: d = (0, -1)
    elif sy == 0: d = (1, 0)
    else: d = (-1, 0)
    seen = set()
    q = deque([(sy, sx, d, True)])
    while q:
        y, x, (dy, dx), first = q.popleft()
        if (y, x, dy, dx) in seen:
            continue
        seen.add((y, x, dy, dx))
        y0, x0 = y, x
        steps = 0
        painted = False
        end = "the border"
        while True:
            ny, nx = y + dy, x + dx
            if not (0 <= ny < H and 0 <= nx < W):
                break
            if g[ny, nx] != bg and g[ny, nx] != 2:
                if steps >= 2 or first:
                    end = "an obstacle, so it splits perpendicular"
                    q.append((y, x, (dx, dy), False))
                    q.append((y, x, (-dx, -dy), False))
                else:
                    end = "an obstacle after only one step, so it just stops"
                break
            y, x = ny, nx
            steps += 1
            if out[y, x] != 2:
                out[y, x] = 2
                painted = True
        if painted:
            emit(out, f"Red ray from ({y0},{x0}) heading ({dy},{dx}) drawn until {end}.")
    emit(out, "Final grid: all red branches drawn.")
    return out
